// Linear is GraphQL-only. ctx.graphql throws on an errors[] array returned with
// HTTP 200 — a DSL `fetch` step would swallow that and store an empty pass set,
// which is the worst failure mode for a compliance check. It also lets us thread
// the pagination cursor through the POST body, which fetchWithCursor (GET-only)
// cannot do.
const PAGE = 250;
const MAX_PAGES = 20;

const QUERY = `query CompAIEmployeeAccess($after: String) {
  organization { id name urlKey }
  users(first: ${PAGE}, after: $after) {
    nodes { id name displayName email active admin guest createdAt }
    pageInfo { hasNextPage endCursor }
  }
}`;

const nodes = [];
let org = null;
let after = null;
let truncated = false;

for (let page = 0; page < MAX_PAGES; page++) {
  const data = await ctx.graphql(QUERY, { after });
  org = org || data.organization || null;

  const users = data.users || {};
  nodes.push(...(users.nodes || []));

  const info = users.pageInfo || {};
  if (!info.hasNextPage) break;
  after = info.endCursor;

  // Runaway guard. Announce truncation rather than silently reporting a partial
  // roster as if it were the whole workspace.
  if (page === MAX_PAGES - 1) truncated = true;
}

if (truncated) {
  ctx.warn(
    `Linear member list truncated at ${nodes.length} records after ${MAX_PAGES} pages; some members were not reviewed.`,
  );
}

const checkedAt = new Date().toISOString();
const workspace = (org && org.name) || null;
const activeMembers = nodes.filter((u) => u.active);

ctx.log(
  `Linear: ${nodes.length} members (${activeMembers.length} active)` +
    (workspace ? ` in ${workspace}` : ''),
);

// Never store zero rows — an empty run is indistinguishable from "no evidence
// collected". One org-level row records that the review ran and found nobody.
if (activeMembers.length === 0) {
  ctx.pass({
    title: 'Employee Access List',
    resourceType: 'organization',
    resourceId: (org && org.urlKey) || 'linear',
    description: `No active members found (${nodes.length} member records inspected)`,
    evidence: { totalUsers: 0, inspectedUsers: nodes.length, truncated, checkedAt },
  });
  return;
}

// One row per person, resourceId = lowercased email, so person-scoped features
// can join these results to org members through CheckResultsService. Access is
// an inventory, not a violation — every person row emits as pass. Mirrors
// manifests/google-workspace/checks/employee-access.ts.
for (const u of activeMembers) {
  const email = String(u.email || '').toLowerCase().trim();
  if (!email) {
    ctx.warn(`Skipping Linear member ${u.id}: no email on record`);
    continue;
  }

  const role = u.admin ? 'Admin' : u.guest ? 'Guest' : 'Member';

  ctx.pass({
    title: 'Employee Access',
    resourceType: 'user',
    resourceId: email,
    description: `${u.name || u.displayName || email} has access to Linear as ${role}`,
    evidence: {
      email,
      name: u.name || u.displayName || null,
      role,
      roles: [role],
      isAdmin: Boolean(u.admin),
      isGuest: Boolean(u.guest),
      externalId: u.id,
      workspace,
      createdAt: u.createdAt || null,
      truncated,
      checkedAt,
    },
  });
}
